     1	package hotel.messages;
     2	
     3	import java.util.ArrayList;
     4	import java.util.List;
     5	
     6	/**
     7	 * Sends e-mails to guests, after the inn's message rules. Every message that comes out of the rules is kept in the
     8	 * list of sent messages, blocked ones included.
     9	 */
    10	public final class EmailSender {
    11	
    12	    private final SentMessages sentMessages;
    13	    private final List<MessageRule> rules;
    14	
    15	    public EmailSender(SentMessages sentMessages, List<MessageRule> rules) {
    16	        this.sentMessages = sentMessages;
    17	        this.rules = rules;
    18	    }
    19	
    20	    /** Returns the first message kept: the one for the guest (or its replacement), not the extra copies. */
    21	    public Message send(String to, String subject, String body) {
    22	        List<Outgoing> outgoing = List.of(Outgoing.toSend(to, subject, body));
    23	        for (MessageRule rule : rules) {
    24	            List<Outgoing> next = new ArrayList<>();
    25	            for (Outgoing message : outgoing) {
    26	                if (message.isBlocked()) {
    27	                    next.add(message);
    28	                } else {
    29	                    next.addAll(rule.apply(message));
    30	                }
    31	            }
    32	            outgoing = next;
    33	        }
    34	        Message first = null;
    35	        for (Outgoing message : outgoing) {
    36	            Message kept = sentMessages.add("EMAIL", message);
    37	            if (first == null) {
    38	                first = kept;
    39	            }
    40	        }
    41	        return first;
    42	    }
    43	}
